#ifndef MK_UNICODE_DATA_H
#define MK_UNICODE_DATA_H

/* The Unicode normalization tables, generated by tools/generate_unicode_data.py.
 * Every array is sorted by its first code point so lookups can bisect. */

#include <stddef.h>

typedef struct mk_unicode_tables {
    /* Canonical combining classes; code points absent here have class 0. */
    const unsigned int *ccc_code_points;
    const unsigned char *ccc_classes;
    size_t ccc_count;

    /* Full canonical decompositions, already applied recursively. Hangul
     * syllables are not listed: they decompose algorithmically. */
    const unsigned int *decomposition_code_points;
    const unsigned short *decomposition_offsets;
    const unsigned char *decomposition_lengths;
    const unsigned int *decomposition_pool;
    size_t decomposition_count;

    /* Primary composites, sorted by (first, second). */
    const unsigned int *composition_first;
    const unsigned int *composition_second;
    const unsigned int *composition_result;
    size_t composition_count;
} mk_unicode_tables;

extern const mk_unicode_tables mki_unicode_tables;

/* The Unicode version the tables were generated from, such as "15.1.0". */
extern const char *const mki_unicode_version;

#endif
